// Fixed-step battle model: a line-by-line port of the Unity template's BattleSimulation (Core/Gameplay:
// BattleSimulation.cs, CombatExtensions.cs, BattleCheckpoint.cs, BattleStateHash.cs). Iteration orders, removal
// semantics and the order of every floating-point operation follow the C# code, so a battle replayed here matches the
// client's bit for bit (test/battle_parity_test.ts checks it against fixtures generated by the C# code).
// Coordinates grow from the defended edge (0) to the enemy entrance (columns + 0.5).

import {
  AbilityResult, BattleContentError, BattleEventKind, DEFENDER_ROLES, ABILITY_EFFECTS, MatchPhase, PlacementResult,
  defenderStats, requireNumber,
  type AbilityDefinition, type BattleEvent, type BattleSettings, type DefenderDefinition, type DefenderStats, type EnemyDefinition,
  type EnemyPhase, type SpawnGroup, type WaveDefinition,
} from "./definitions.js";
import { BinaryWriter, Fnv1a, sha256Hex } from "./hashing.js";

const EPSILON = 0.000001;
const MAX_QUEUED_EVENTS = 2048;
const RULES_VERSION = "standard.v1";

export class DefenderState {
  level = 0;
  health: number;
  investedEnergy: number;
  nextAction: number;

  constructor(
    readonly id: number,
    readonly definition: DefenderDefinition,
    readonly lane: number,
    readonly column: number,
    time: number,
  ) {
    this.health = this.stats.health;
    this.investedEnergy = definition.cost;
    // Generators wait a full cycle; shooters can acquire a target immediately.
    this.nextAction = time + (definition.role === "Generator" ? this.stats.interval : 0);
  }

  get x(): number {
    return this.column + 0.5;
  }

  get stats(): DefenderStats {
    return this.definition.levels[this.level];
  }
}

export class EnemyState {
  health: number;
  slowFraction = 0;
  slowUntil = 0;
  nextAttack = 0;
  phaseIndex = -1;
  stunUntil = 0;
  burnDamagePerSecond = 0;
  burnUntil = 0;
  nextPulse = 0;

  constructor(
    readonly id: number,
    readonly definition: EnemyDefinition,
    readonly lane: number,
    public x: number,
  ) {
    this.health = definition.health;
  }

  get activePhase(): EnemyPhase | null {
    return this.phaseIndex >= 0 ? this.definition.phases[this.phaseIndex] : null;
  }
}

export class ProjectileState {
  remainingHits: number;
  hitIds: number[] | null;

  constructor(
    readonly id: number,
    readonly lane: number,
    public x: number,
    readonly payload: DefenderStats,
    readonly cardId: string,
    readonly cardLevel: number,
  ) {
    this.remainingHits = payload.pierceCount;
    this.hitIds = this.remainingHits > 1 ? [] : null;
  }
}

/** Shape of the C# BattleCheckpoint (JSON field names included): what a replica restores to resynchronize. */
export type BattleCheckpoint = {
  version: number;
  contentHash: string;
  ticks: number;
  random: number;
  nextId: number;
  nextSpawn: number;
  currentWave: number;
  baseHealth: number;
  kills: number;
  spawned: number;
  escaped: number;
  placed: number;
  upgraded: number;
  abilitiesUsed: number;
  phase: MatchPhase;
  energy: number;
  guards: boolean[];
  defenders: { id: number; lane: number; column: number; level: number; cardId: string; health: number; nextAction: number; invested: number }[];
  enemies: {
    id: number; lane: number; phase: number; enemyId: string; x: number; health: number; slow: number; slowUntil: number;
    stunUntil: number; burn: number; burnUntil: number; nextAttack: number; nextPulse: number;
  }[];
  projectiles: { id: number; lane: number; level: number; remaining: number; cardId: string; x: number; hitIds: number[] }[];
  cardCooldowns: { id: string; until: number }[];
  abilityCooldowns: { id: string; until: number }[];
};

type ScheduledSpawn = { time: number; group: SpawnGroup; order: number };

/** Removes the first occurrence (C# List.Remove). */
function removeFirst<T>(list: T[], item: T): void {
  const index = list.indexOf(item);
  if (index >= 0) list.splice(index, 1);
}

export class BattleSimulation {
  readonly defenders: DefenderState[] = [];
  readonly enemies: EnemyState[] = [];
  readonly projectiles: ProjectileState[] = [];
  phase = MatchPhase.Running;
  energy: number;
  baseHealth: number;
  currentWave = 0;
  /** Enemies destroyed by the crew. A lane guard sweep removes enemies without counting them. */
  kills = 0;
  totalSpawned = 0;
  escapedCount = 0;
  placedCount = 0;
  upgradedCount = 0;
  abilitiesUsed = 0;

  private readonly enemyTurnOrder: EnemyState[] = [];
  private readonly laneEnemies: EnemyState[][];
  private readonly cards = new Map<string, DefenderDefinition>();
  private readonly recharges = new Map<string, number>();
  private readonly abilities = new Map<string, AbilityDefinition>();
  private readonly abilityRecharges = new Map<string, number>();
  private readonly events: BattleEvent[] = [];
  private readonly schedule: ScheduledSpawn[] = [];
  private readonly waves: readonly WaveDefinition[];
  private readonly enemyDefinitions = new Map<string, EnemyDefinition>();
  private readonly board: (DefenderState | null)[][];
  private readonly guards: boolean[];
  private readonly initialSeed: number;
  private nextId = 1;
  private nextSpawn = 0;
  private tickCount = 0;
  private random: number;
  private cachedContentHash: string | null = null;

  constructor(
    readonly settings: BattleSettings,
    deck: readonly DefenderDefinition[],
    waveDefinitions: readonly WaveDefinition[],
    seed = 1,
    abilityDefinitions: readonly AbilityDefinition[] = [],
  ) {
    if (!settings) throw new BattleContentError("Settings are required.");
    if (!Number.isInteger(seed) || seed < 0 || seed > 0xffffffff) throw new BattleContentError("The seed must be a 32-bit unsigned integer.");
    this.initialSeed = seed === 0 ? 1 : seed;
    this.laneEnemies = Array.from({ length: settings.lanes }, (): EnemyState[] => []);
    for (const ability of abilityDefinitions) {
      if (!ability || this.abilities.has(ability.id)) throw new BattleContentError("Ability IDs must be unique.");
      this.abilities.set(ability.id, ability);
    }
    if (!deck || !waveDefinitions) throw new BattleContentError("Deck and waves are required.");
    for (const card of deck) {
      if (!card || this.cards.has(card.id)) throw new BattleContentError("Deck IDs must be unique and cards non-null.");
      this.cards.set(card.id, card);
    }
    if (this.cards.size === 0) throw new BattleContentError("A deck is required.");
    if (waveDefinitions.length === 0 || waveDefinitions.some((x) => !x)) throw new BattleContentError("Complete waves are required.");
    this.waves = [...waveDefinitions];
    for (let i = 0; i < this.waves.length; i++) {
      if (i > 0 && this.waves[i].startTime < this.waves[i - 1].startTime) throw new BattleContentError("Wave times must be in ascending order.");
      for (const group of this.waves[i].groups) {
        const existing = this.enemyDefinitions.get(group.enemy.id);
        if (existing) {
          if (enemySignature(existing) !== enemySignature(group.enemy)) throw new BattleContentError(`An enemy ID has conflicting definitions: ${group.enemy.id}`);
        } else this.enemyDefinitions.set(group.enemy.id, group.enemy);
        if (group.lane >= settings.lanes) throw new BattleContentError("Spawn lane is outside the board.");
        if (group.column >= settings.columns) throw new BattleContentError("Spawn column is outside the board.");
        if (this.schedule.length + group.count > 100000) throw new BattleContentError("Encounter exceeds 100000 enemies.");
        for (let j = 0; j < group.count; j++) {
          const spawnTime = requireNumber(this.waves[i].startTime + group.delay + j * group.interval, "Scheduled spawn time");
          this.schedule.push({ time: spawnTime, group, order: this.schedule.length });
        }
      }
    }
    this.schedule.sort((a, b) => (a.time !== b.time ? (a.time < b.time ? -1 : 1) : a.order - b.order));
    this.random = this.initialSeed;
    this.board = Array.from({ length: settings.lanes }, () => new Array<DefenderState | null>(settings.columns).fill(null));
    this.guards = new Array<boolean>(settings.lanes).fill(settings.laneGuards);
    this.energy = settings.startingEnergy;
    this.baseHealth = settings.baseHealth;
  }

  // ------------------------------------------------------------------ queries
  get ticks(): number {
    return this.tickCount;
  }

  get time(): number {
    return this.tickCount * this.settings.tickSeconds;
  }

  get totalWaves(): number {
    return this.waves.length;
  }

  get cardDefinitions(): DefenderDefinition[] {
    return [...this.cards.values()];
  }

  get enemyDefinitionList(): EnemyDefinition[] {
    return [...this.enemyDefinitions.values()];
  }

  get abilityList(): AbilityDefinition[] {
    return [...this.abilities.values()];
  }

  get isOver(): boolean {
    return this.phase === MatchPhase.Victory || this.phase === MatchPhase.Defeat;
  }

  isInside(lane: number, column: number): boolean {
    return Number.isInteger(lane) && Number.isInteger(column) && lane >= 0 && lane < this.settings.lanes && column >= 0 && column < this.settings.columns;
  }

  getDefender(lane: number, column: number): DefenderState | null {
    return this.isInside(lane, column) ? this.board[lane][column] : null;
  }

  hasGuard(lane: number): boolean {
    return lane >= 0 && lane < this.guards.length && this.guards[lane];
  }

  rechargeRemaining(cardId: string): number {
    const until = cardId != null ? this.recharges.get(cardId) : undefined;
    return until !== undefined ? Math.max(0, until - this.time) : 0;
  }

  abilityCooldown(id: string): number {
    const until = id != null ? this.abilityRecharges.get(id) : undefined;
    return until !== undefined ? Math.max(0, until - this.time) : 0;
  }

  /** Removes and returns the queued events (oldest first). */
  drainEvents(): BattleEvent[] {
    return this.events.splice(0, this.events.length);
  }

  private emit(kind: BattleEventKind, id = 0, lane = -1, amount = 0): void {
    // Bounded diagnostic history for consumers that do not subscribe.
    if (this.events.length === MAX_QUEUED_EVENTS) this.events.shift();
    this.events.push({ kind, entityId: id, lane, amount, time: this.time });
  }

  // ------------------------------------------------------------------ commands
  canPlace(cardId: string, lane: number, column: number): PlacementResult {
    if (this.phase !== MatchPhase.Running) return PlacementResult.MatchNotRunning;
    const card = cardId != null ? this.cards.get(cardId) : undefined;
    if (!card) return PlacementResult.UnknownCard;
    if (!this.isInside(lane, column)) return PlacementResult.OutsideBoard;
    if (this.board[lane][column] !== null) return PlacementResult.Occupied;
    if (this.rechargeRemaining(cardId) > EPSILON) return PlacementResult.CoolingDown;
    if (this.energy + EPSILON < card.cost) return PlacementResult.InsufficientEnergy;
    return PlacementResult.Success;
  }

  tryPlace(cardId: string, lane: number, column: number): PlacementResult {
    const result = this.canPlace(cardId, lane, column);
    if (result !== PlacementResult.Success) return result;
    const card = this.cards.get(cardId);
    const defender = new DefenderState(this.nextId++, card, lane, column, this.time);
    this.energy = Math.max(0, this.energy - card.cost);
    this.recharges.set(cardId, this.time + card.recharge);
    this.defenders.push(defender);
    this.board[lane][column] = defender;
    this.placedCount++;
    this.emit(BattleEventKind.Placed, defender.id, lane, card.cost);
    return PlacementResult.Success;
  }

  tryUpgrade(lane: number, column: number): boolean {
    const defender = this.getDefender(lane, column);
    if (this.phase !== MatchPhase.Running || defender === null || defender.level + 1 >= defender.definition.levels.length) return false;
    const next = defender.definition.levels[defender.level + 1];
    if (this.energy + EPSILON < next.upgradeCost) return false;
    const healthRatio = defender.health / defender.stats.health;
    this.energy = Math.max(0, this.energy - next.upgradeCost);
    defender.investedEnergy += next.upgradeCost;
    defender.level++;
    this.upgradedCount++;
    defender.health = healthRatio * next.health;
    // Upgrading cannot reset an attack/production cycle to farm instant activations.
    defender.nextAction = Math.max(defender.nextAction, this.time + next.interval);
    this.emit(BattleEventKind.Upgraded, defender.id, lane, next.upgradeCost);
    return true;
  }

  tryRemove(lane: number, column: number): boolean {
    const defender = this.getDefender(lane, column);
    if (this.phase !== MatchPhase.Running || defender === null) return false;
    const refund = Math.floor(defender.investedEnergy * this.settings.refundFraction);
    this.addEnergy(refund);
    this.removeDefender(defender);
    this.emit(BattleEventKind.Removed, defender.id, lane, refund);
    return true;
  }

  tryCast(id: string, lane: number): AbilityResult {
    if (this.phase !== MatchPhase.Running) return AbilityResult.MatchNotRunning;
    const ability = id != null ? this.abilities.get(id) : undefined;
    if (!ability) return AbilityResult.UnknownAbility;
    if (!Number.isInteger(lane) || lane < 0 || lane >= this.settings.lanes) return AbilityResult.OutsideBoard;
    if (this.abilityCooldown(id) > EPSILON) return AbilityResult.CoolingDown;
    if (this.energy + EPSILON < ability.cost) return AbilityResult.InsufficientEnergy;
    const target = ability.effect === "Repair"
      ? this.defenders.some((x) => x.lane === lane && x.health < x.stats.health)
      : this.laneEnemies[lane].length > 0;
    if (!target) return AbilityResult.NoTarget;
    this.energy = Math.max(0, this.energy - ability.cost);
    this.abilityRecharges.set(id, this.time + ability.cooldown);
    this.abilitiesUsed++;
    if (ability.effect === "Repair") {
      for (const defender of this.defenders) {
        if (defender.lane === lane) defender.health = Math.min(defender.stats.health, defender.health + ability.power);
      }
    } else {
      const payload = ability.effect === "LaneStrike"
        ? defenderStats({ health: 1, damage: ability.power })
        : defenderStats({ health: 1, stunDuration: ability.power });
      const targets = this.laneEnemies[lane];
      for (let i = targets.length - 1; i >= 0; i--) this.hit(targets[i], payload);
    }
    this.emit(BattleEventKind.AbilityCast, 0, lane, ability.cost);
    return AbilityResult.Success;
  }

  setPaused(paused: boolean): void {
    if (paused && this.phase === MatchPhase.Running) this.phase = MatchPhase.Paused;
    else if (!paused && this.phase === MatchPhase.Paused) this.phase = MatchPhase.Running;
  }

  // ------------------------------------------------------------------ tick
  step(): void {
    if (this.phase !== MatchPhase.Running) return;
    this.tickCount++;
    this.addEnergy(this.settings.passiveEnergyPerSecond * this.settings.tickSeconds);
    while (this.currentWave < this.waves.length && this.waves[this.currentWave].startTime <= this.time + EPSILON) {
      this.currentWave++;
      this.emit(BattleEventKind.WaveStarted, 0, -1, this.currentWave);
    }
    while (this.nextSpawn < this.schedule.length && this.schedule[this.nextSpawn].time <= this.time + EPSILON) {
      const group = this.schedule[this.nextSpawn++].group;
      const lane = group.lane < 0 ? this.randomLane() : group.lane;
      const enemy = new EnemyState(this.nextId++, group.enemy, lane, group.column < 0 ? this.settings.columns + 0.5 : group.column + 0.5);
      this.enemies.push(enemy);
      this.laneEnemies[lane].push(enemy);
      this.totalSpawned++;
      this.emit(BattleEventKind.EnemySpawned, enemy.id, lane);
    }
    this.actStatuses();
    this.actDefenders();
    this.moveProjectiles();
    this.actEnemies();
    if (this.phase === MatchPhase.Running && this.nextSpawn === this.schedule.length && this.enemies.length === 0) {
      this.phase = MatchPhase.Victory;
      this.projectiles.length = 0;
      this.emit(BattleEventKind.Victory);
    }
  }

  private addEnergy(amount: number): void {
    this.energy = Math.min(this.settings.energyCap, this.energy + amount);
  }

  /** xorshift32 on an unsigned 32-bit state (C#: uint arithmetic). */
  private randomLane(): number {
    let r = this.random;
    r = (r ^ (r << 13)) >>> 0;
    r = (r ^ (r >>> 17)) >>> 0;
    r = (r ^ (r << 5)) >>> 0;
    this.random = r;
    return r % this.settings.lanes;
  }

  private firstTarget(lane: number, from: number, to: number, excluded: number[] | null = null): EnemyState | null {
    let target: EnemyState | null = null;
    for (const enemy of this.laneEnemies[lane]) {
      if (enemy.health > 0 && (excluded === null || !excluded.includes(enemy.id)) && enemy.x >= from - EPSILON && enemy.x <= to + EPSILON &&
        (target === null || enemy.x < target.x)) target = enemy;
    }
    return target;
  }

  private actDefenders(): void {
    for (const defender of this.defenders) {
      if (this.time + EPSILON < defender.nextAction) continue;
      const stats = defender.stats;
      if (defender.definition.role === "Generator") {
        this.addEnergy(stats.production);
        defender.nextAction = this.time + stats.interval;
        this.emit(BattleEventKind.EnergyProduced, defender.id, defender.lane, stats.production);
      } else if (defender.definition.role === "Shooter" && this.firstTarget(defender.lane, defender.x, defender.x + stats.range) !== null) {
        this.projectiles.push(new ProjectileState(this.nextId++, defender.lane, defender.x, stats, defender.definition.id, defender.level));
        defender.nextAction = this.time + stats.interval;
        this.emit(BattleEventKind.Shot, defender.id, defender.lane);
      }
    }
  }

  private moveProjectiles(): void {
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const projectile = this.projectiles[i];
      const end = projectile.x + projectile.payload.projectileSpeed * this.settings.tickSeconds;
      while (projectile.remainingHits > 0) {
        const target = this.firstTarget(projectile.lane, projectile.x - 0.15, end + 0.15, projectile.hitIds);
        if (target === null) break;
        const impactX = target.x;
        projectile.hitIds?.push(target.id);
        if (projectile.payload.splashRadius <= 0) this.hit(target, projectile.payload);
        else {
          const targets = this.laneEnemies[projectile.lane];
          for (let e = targets.length - 1; e >= 0; e--) {
            const enemy = targets[e];
            if (Math.abs(enemy.x - impactX) <= projectile.payload.splashRadius) this.hit(enemy, projectile.payload);
          }
        }
        projectile.remainingHits--;
      }
      if (projectile.remainingHits === 0 || end > this.settings.columns + 1) this.projectiles.splice(i, 1);
      else projectile.x = end;
    }
  }

  private hit(enemy: EnemyState, payload: DefenderStats): void {
    const damage = requireNumber(payload.damage * (1 - enemy.definition.armor) * (enemy.activePhase?.incomingDamageMultiplier ?? 1), "Projectile damage result");
    enemy.health -= damage;
    this.emit(BattleEventKind.EnemyDamaged, enemy.id, enemy.lane, damage);
    if (payload.slowFraction > 0 && payload.slowDuration > 0) {
      // The strongest active slow wins. A weaker hit cannot extend a stronger effect.
      if (this.time >= enemy.slowUntil || payload.slowFraction > enemy.slowFraction) {
        enemy.slowFraction = payload.slowFraction;
        enemy.slowUntil = this.time + payload.slowDuration;
      } else if (payload.slowFraction === enemy.slowFraction) {
        enemy.slowUntil = Math.max(enemy.slowUntil, this.time + payload.slowDuration);
      }
    }
    enemy.stunUntil = Math.max(enemy.stunUntil, this.time + payload.stunDuration);
    if (payload.burnDamagePerSecond > 0 && payload.burnDuration > 0) {
      if (this.time >= enemy.burnUntil || payload.burnDamagePerSecond > enemy.burnDamagePerSecond) {
        enemy.burnDamagePerSecond = payload.burnDamagePerSecond;
        enemy.burnUntil = this.time + payload.burnDuration;
      } else if (payload.burnDamagePerSecond === enemy.burnDamagePerSecond) {
        enemy.burnUntil = Math.max(enemy.burnUntil, this.time + payload.burnDuration);
      }
    }
    if (enemy.health <= 0) this.kill(enemy, true);
    else this.updateBossPhase(enemy);
  }

  private kill(enemy: EnemyState, reward: boolean): void {
    enemy.health = 0;
    removeFirst(this.enemies, enemy);
    removeFirst(this.laneEnemies[enemy.lane], enemy);
    if (reward) {
      this.kills++;
      this.addEnergy(enemy.definition.reward);
    }
    this.emit(BattleEventKind.EnemyKilled, enemy.id, enemy.lane, reward ? enemy.definition.reward : 0);
  }

  private removeDefender(defender: DefenderState): void {
    this.board[defender.lane][defender.column] = null;
    removeFirst(this.defenders, defender);
  }

  private actStatuses(): void {
    for (let i = this.enemies.length - 1; i >= 0; i--) {
      const enemy = this.enemies[i];
      const duration = Math.min(this.settings.tickSeconds, Math.max(0, enemy.burnUntil - (this.time - this.settings.tickSeconds)));
      if (duration <= 0 || enemy.burnDamagePerSecond <= 0) continue;
      // Burn ignores armor. A phase's incoming-damage multiplier still applies.
      const damage = requireNumber(enemy.burnDamagePerSecond * duration * (enemy.activePhase?.incomingDamageMultiplier ?? 1), "Burn damage");
      enemy.health -= damage;
      this.emit(BattleEventKind.EnemyDamaged, enemy.id, enemy.lane, damage);
      if (enemy.health <= 0) this.kill(enemy, true);
      else this.updateBossPhase(enemy);
    }
  }

  private updateBossPhase(enemy: EnemyState): void {
    const phases = enemy.definition.phases;
    while (enemy.phaseIndex + 1 < phases.length && enemy.health / enemy.definition.health <= phases[enemy.phaseIndex + 1].healthFraction) {
      enemy.phaseIndex++;
      enemy.nextPulse = this.time + enemy.activePhase.pulseInterval;
      this.emit(BattleEventKind.BossPhaseChanged, enemy.id, enemy.lane, enemy.phaseIndex + 1);
    }
  }

  private bossPulse(enemy: EnemyState): void {
    const phase = enemy.activePhase;
    if (phase === null || phase.pulseInterval <= 0 || this.time + EPSILON < enemy.nextPulse) return;
    enemy.nextPulse = this.time + phase.pulseInterval;
    this.emit(BattleEventKind.EnemyAttacked, enemy.id, enemy.lane, phase.pulseDamage);
    for (let i = this.defenders.length - 1; i >= 0; i--) {
      const defender = this.defenders[i];
      if (defender.lane !== enemy.lane) continue;
      defender.health -= phase.pulseDamage;
      this.emit(BattleEventKind.DefenderDamaged, defender.id, defender.lane, phase.pulseDamage);
      if (defender.health <= 0) {
        this.removeDefender(defender);
        this.emit(BattleEventKind.DefenderDestroyed, defender.id, defender.lane);
      }
    }
  }

  private actEnemies(): void {
    const order = this.enemyTurnOrder;
    order.length = 0;
    order.push(...this.enemies);
    for (let i = order.length - 1; i >= 0; i--) {
      const enemy = order[i];
      if (enemy.health <= 0) continue;
      if (this.time >= enemy.slowUntil) enemy.slowFraction = 0;
      if (this.time < enemy.stunUntil) continue;
      this.bossPulse(enemy);
      let blocker: DefenderState | null = null;
      for (let column = Math.min(this.settings.columns - 1, Math.floor(enemy.x - 0.5)); column >= 0; column--) {
        if (this.board[enemy.lane][column] !== null) {
          blocker = this.board[enemy.lane][column];
          break;
        }
      }
      const stop = blocker !== null ? blocker.x + enemy.definition.reach : 0;
      if (blocker !== null && enemy.x <= stop + EPSILON) {
        if (this.time + EPSILON >= enemy.nextAttack) {
          enemy.nextAttack = this.time + enemy.definition.attackInterval;
          const damage = requireNumber(enemy.definition.damage * (enemy.activePhase?.damageMultiplier ?? 1), "Melee damage result");
          this.emit(BattleEventKind.EnemyAttacked, enemy.id, enemy.lane, damage);
          blocker.health -= damage;
          this.emit(BattleEventKind.DefenderDamaged, blocker.id, blocker.lane, damage);
          if (blocker.health <= 0) {
            this.removeDefender(blocker);
            this.emit(BattleEventKind.DefenderDestroyed, blocker.id, blocker.lane);
          }
        }
      } else {
        enemy.x = Math.max(stop,
          enemy.x - enemy.definition.speed * (enemy.activePhase?.speedMultiplier ?? 1) * (1 - enemy.slowFraction) * this.settings.tickSeconds);
      }

      if (enemy.x > 0) continue;
      if (this.guards[enemy.lane]) {
        this.guards[enemy.lane] = false;
        this.emit(BattleEventKind.GuardTriggered, enemy.id, enemy.lane);
        // Remove every current enemy in this lane without granting economy rewards.
        const lane = this.laneEnemies[enemy.lane];
        for (let e = lane.length - 1; e >= 0; e--) this.kill(lane[e], false);
      } else {
        enemy.health = 0;
        this.escapedCount++;
        removeFirst(this.enemies, enemy);
        removeFirst(this.laneEnemies[enemy.lane], enemy);
        this.baseHealth = Math.max(0, this.baseHealth - enemy.definition.baseDamage);
        this.emit(BattleEventKind.BaseDamaged, enemy.id, enemy.lane, enemy.definition.baseDamage);
        if (this.baseHealth === 0) {
          this.phase = MatchPhase.Defeat;
          this.projectiles.length = 0;
          this.emit(BattleEventKind.Defeat);
          return;
        }
      }
    }
  }

  // ------------------------------------------------------------------ fingerprints and checkpoints
  /** SHA-256 of the content (C# BattleSimulation.ContentHash); a replica's checkpoint restore requires the same value. */
  get contentHash(): string {
    if (this.cachedContentHash !== null) return this.cachedContentHash;
    const s = this.settings;
    const w = new BinaryWriter();
    w.string("ctd.battle.v2").string(RULES_VERSION).uint(this.initialSeed);
    w.int(s.lanes).int(s.columns).int(s.startingEnergy).int(s.energyCap);
    w.int(s.baseHealth).double(s.passiveEnergyPerSecond).double(s.tickSeconds);
    w.double(s.refundFraction).bool(s.laneGuards);
    const ids = [...this.cards.keys()].sort(compareOrdinal);
    w.int(ids.length);
    for (const id of ids) {
      const card = this.cards.get(id);
      w.string(card.id).string(card.name).int(DEFENDER_ROLES.indexOf(card.role));
      w.int(card.cost).double(card.recharge).int(card.levels.length);
      for (const stats of card.levels) writeStats(w, stats);
    }
    w.int(this.waves.length);
    for (const wave of this.waves) {
      w.double(wave.startTime).int(wave.groups.length);
      for (const group of wave.groups) {
        w.string(enemySignature(group.enemy)).int(group.count).int(group.lane).double(group.delay).double(group.interval).int(group.column);
      }
    }
    const abilityIds = [...this.abilities.keys()].sort(compareOrdinal);
    w.int(abilityIds.length);
    for (const id of abilityIds) {
      const a = this.abilities.get(id);
      w.string(a.id).int(ABILITY_EFFECTS.indexOf(a.effect)).int(a.cost).double(a.cooldown).double(a.power);
    }
    this.cachedContentHash = sha256Hex(w.toBuffer());
    return this.cachedContentHash;
  }

  /** Same value as the C# BattleSimulation.StateHash() for the same state. */
  stateHash(): number {
    const h = new Fnv1a();
    h.long(this.tickCount).uint(this.random).int(this.nextId).int(this.nextSpawn).int(this.currentWave).int(this.baseHealth);
    h.int(this.kills).int(this.totalSpawned).int(this.escapedCount).int(this.placedCount).int(this.upgradedCount).int(this.abilitiesUsed);
    h.int(this.phase).double(this.energy);
    h.int(this.guards.length);
    for (const guard of this.guards) h.int(guard ? 1 : 0);
    h.int(this.defenders.length);
    for (const d of this.defenders) {
      h.int(d.id).text(d.definition.id).int(d.lane).int(d.column).int(d.level);
      h.double(d.health).double(d.nextAction).long(d.investedEnergy);
    }
    h.int(this.enemies.length);
    for (const e of this.enemies) {
      h.int(e.id).text(e.definition.id).int(e.lane).double(e.x).double(e.health).double(e.slowFraction);
      h.double(e.slowUntil).double(e.stunUntil).double(e.burnDamagePerSecond).double(e.burnUntil);
      h.double(e.nextAttack).double(e.nextPulse).int(e.phaseIndex);
    }
    h.int(this.projectiles.length);
    for (const p of this.projectiles) {
      h.int(p.id).int(p.lane).double(p.x).text(p.cardId).int(p.cardLevel).int(p.remainingHits);
      h.int(p.hitIds?.length ?? 0);
      if (p.hitIds) for (const id of p.hitIds) h.int(id);
    }
    hashTimers(h, this.recharges);
    hashTimers(h, this.abilityRecharges);
    return h.value;
  }

  /** Full state in the C# BattleCheckpoint shape (a replica restores it with BattleSimulation.Restore). */
  capture(): BattleCheckpoint {
    return {
      version: 1,
      contentHash: this.contentHash,
      ticks: this.tickCount,
      random: this.random,
      nextId: this.nextId,
      nextSpawn: this.nextSpawn,
      currentWave: this.currentWave,
      baseHealth: this.baseHealth,
      kills: this.kills,
      spawned: this.totalSpawned,
      escaped: this.escapedCount,
      placed: this.placedCount,
      upgraded: this.upgradedCount,
      abilitiesUsed: this.abilitiesUsed,
      phase: this.phase,
      energy: this.energy,
      guards: [...this.guards],
      defenders: this.defenders.map((d) => ({
        id: d.id, lane: d.lane, column: d.column, level: d.level, cardId: d.definition.id, health: d.health, nextAction: d.nextAction, invested: d.investedEnergy,
      })),
      enemies: this.enemies.map((e) => ({
        id: e.id, lane: e.lane, phase: e.phaseIndex, enemyId: e.definition.id, x: e.x, health: e.health, slow: e.slowFraction, slowUntil: e.slowUntil,
        stunUntil: e.stunUntil, burn: e.burnDamagePerSecond, burnUntil: e.burnUntil, nextAttack: e.nextAttack, nextPulse: e.nextPulse,
      })),
      projectiles: this.projectiles.map((p) => ({
        id: p.id, lane: p.lane, level: p.cardLevel, remaining: p.remainingHits, cardId: p.cardId, x: p.x, hitIds: p.hitIds ? [...p.hitIds] : [],
      })),
      cardCooldowns: [...this.recharges].map(([id, until]) => ({ id, until })),
      abilityCooldowns: [...this.abilityRecharges].map(([id, until]) => ({ id, until })),
    };
  }
}

/** C# StringComparer.Ordinal (UTF-16 code units). */
export function compareOrdinal(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

function writeStats(w: BinaryWriter, s: DefenderStats): void {
  w.double(s.health).double(s.damage).double(s.interval).double(s.range).double(s.projectileSpeed).double(s.splashRadius);
  w.double(s.slowFraction).double(s.slowDuration).int(s.production).int(s.upgradeCost);
  w.double(s.stunDuration).double(s.burnDamagePerSecond).double(s.burnDuration).int(s.pierceCount);
}

const signatures = new WeakMap<EnemyDefinition, string>();

/** C# EnemySignature: SHA-256 of the enemy's tuning, identifying conflicting definitions that share an id. */
export function enemySignature(enemy: EnemyDefinition): string {
  const cached = signatures.get(enemy);
  if (cached) return cached;
  const w = new BinaryWriter();
  w.string(enemy.id).double(enemy.health).double(enemy.speed).double(enemy.damage).double(enemy.attackInterval);
  w.double(enemy.armor).int(enemy.reward).int(enemy.baseDamage).double(enemy.reach).int(enemy.phases.length);
  for (const p of enemy.phases) {
    w.double(p.healthFraction).double(p.speedMultiplier).double(p.damageMultiplier).double(p.incomingDamageMultiplier).double(p.pulseInterval).double(p.pulseDamage);
  }
  const signature = sha256Hex(w.toBuffer());
  signatures.set(enemy, signature);
  return signature;
}

function hashTimers(h: Fnv1a, timers: Map<string, number>): void {
  const keys = [...timers.keys()].sort(compareOrdinal);
  h.int(keys.length);
  for (const key of keys) h.text(key).double(timers.get(key));
}
